"use client";

import { useState, useTransition } from "react";

export function SingleReferenceSelect({
  options,
  initialSelectedId,
  createAction,
  hiddenFieldName,
  noneLabel = "— None —",
}: {
  options: { id: string; name: string }[];
  initialSelectedId: string | null;
  createAction: (name: string) => Promise<{ id: string; name: string }>;
  hiddenFieldName: string;
  noneLabel?: string;
}) {
  const [allOptions, setAllOptions] = useState(options);
  const [selectedId, setSelectedId] = useState<string>(initialSelectedId ?? "");
  const [newName, setNewName] = useState("");
  const [adding, setAdding] = useState(false);
  const [isPending, startTransition] = useTransition();

  function handleAdd() {
    const name = newName.trim();
    if (!name) return;
    startTransition(async () => {
      const created = await createAction(name);
      setAllOptions((prev) => [...prev, created]);
      setSelectedId(created.id);
      setNewName("");
      setAdding(false);
    });
  }

  return (
    <div>
      <select
        value={selectedId}
        onChange={(e) => setSelectedId(e.target.value)}
        className="w-full rounded-[var(--radius-control)] border border-console-border bg-console-bg px-3 py-2 text-sm text-console-text focus:border-console-accent"
      >
        <option value="">{noneLabel}</option>
        {allOptions.map((option) => (
          <option key={option.id} value={option.id} title={option.name}>
            {option.name}
          </option>
        ))}
      </select>

      {!adding ? (
        <button
          type="button"
          onClick={() => setAdding(true)}
          className="mt-1.5 text-xs text-console-accent hover:underline"
        >
          + Add new
        </button>
      ) : (
        <div className="mt-1.5 flex gap-2">
          <input
            type="text"
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            placeholder="New publisher name"
            className="flex-1 rounded-[var(--radius-control)] border border-console-border bg-console-bg px-2 py-1 text-sm"
          />
          <button
            type="button"
            onClick={handleAdd}
            disabled={isPending}
            className="rounded-[var(--radius-control)] bg-console-accent px-2 py-1 text-xs font-medium text-console-bg disabled:opacity-50"
          >
            {isPending ? "Adding…" : "Add & use"}
          </button>
        </div>
      )}

      <input type="hidden" name={hiddenFieldName} value={selectedId} />
    </div>
  );
}
